/**
 * How Genji cypress fan (`genji-hi-ogi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/genji-hi-ogi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Rule eight stepped slats and a curved belt with seven bindings. Lay the decorated guard over the fan and pierce a small eye. Hang two pairs of knotted pendants from looped cords.","ja":"段を付けた八枚の骨を引き、七つの留め具のある弧の帯を重ねます。模様のある親骨に小さな要の穴を開け、輪にした紐から二対の結び房を下げます。"};

export default construction;
export { construction, description };
